import pytest
from fastapi import FastAPI, Depends
from functools import partial
from fastapi.testclient import TestClient

def common_dep(q: str = "default"):
    return q

async def async_dep(q: str = "default"):
    return q

class ClassDep:
    def __call__(self, q: str = "default"):
        return q

def test_partial_function():
    app = FastAPI()
    # partial function
    dep = partial(common_dep, q="partial_val")

    @app.get("/")
    def root(val: str = Depends(dep)):
        return {"val": val}

    client = TestClient(app)
    response = client.get("/")
    assert response.json() == {"val": "partial_val"}

def test_partial_async_function():
    app = FastAPI()
    # partial async function
    dep = partial(async_dep, q="partial_async_val")

    @app.get("/")
    async def root(val: str = Depends(dep)):
        return {"val": val}

    client = TestClient(app)
    response = client.get("/")
    assert response.json() == {"val": "partial_async_val"}

def test_partial_class_call():
    app = FastAPI()
    # partial of a callable class instance
    class_dep = ClassDep()
    dep = partial(class_dep, q="partial_class_val")

    @app.get("/")
    def root(val: str = Depends(dep)):
        return {"val": val}

    client = TestClient(app)
    response = client.get("/")
    assert response.json() == {"val": "partial_class_val"}

def test_partial_complex_params():
    app = FastAPI()

    def complex_dep(a: int = 1, b: str = "2"):
        return f"{a}-{b}"

    dep = partial(complex_dep, a=10)

    @app.get("/")
    def root(val: str = Depends(dep), b: str = "override"):
        # b is provided as a dependency param if not provided by partial
        # but here b is not in partial, so it should be resolveable
        return {"val": val}

    client = TestClient(app)
    # Since dep = partial(complex_dep, a=10), it still needs 'b'
    # FastAPI should resolve 'b' from request query if not provided
    response = client.get("/?b=hello")
    assert response.json() == {"val": "10-hello"}

